"use client";
import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";

export default function DashboardPage() {
  const [user, setUser] = useState(null);
  const router = useRouter();

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      router.push("/login");
      return;
    }
    try {
      const payload = JSON.parse(atob(token.split(".")[1]));
      setUser(payload);
    } catch {
      localStorage.removeItem("token");
      router.push("/login");
    }
  }, [router]);

  const handleLogout = () => {
    localStorage.removeItem("token");
    router.push("/login");
  };

  if (!user) return null;

  return (
    <div className="flex flex-col min-h-screen bg-gray-100 px-2 md:px-16 lg:px-64 py-8">
      <header className="flex flex-col md:flex-row items-center justify-between mb-8 gap-4">
        <div>
          <h1 className="text-2xl font-bold">Welcome, {user.fullName || "Patient"}</h1>
          <p className="text-gray-600 text-sm">Your health at a glance</p>
        </div>
      </header>
      <Card className="w-full">
        <CardHeader>
          <CardTitle>Patient Dashboard</CardTitle>
        </CardHeader>
        <CardContent>
          <Tabs defaultValue="doctors" className="w-full">
            <TabsList className="flex flex-wrap gap-2">
              <TabsTrigger value="doctors">Browse/Search Doctors</TabsTrigger>
              <TabsTrigger value="appointments">Book Appointment</TabsTrigger>
              <TabsTrigger value="prescriptions">View Prescriptions</TabsTrigger>
              <TabsTrigger value="history">Health History</TabsTrigger>
            </TabsList>
            <TabsContent value="doctors">
              <div className="my-4">
                <Input placeholder="Search doctors by name, specialty..." className="max-w-md" />
                {/* TODO: Doctor cards/list here */}
                <div className="mt-6 text-center text-gray-400">Doctor list will appear here.</div>
              </div>
            </TabsContent>
            <TabsContent value="appointments">
              <div className="my-4">
                {/* TODO: Appointment booking UI here */}
                <div className="mt-6 text-center text-gray-400">Appointment booking feature coming soon.</div>
              </div>
            </TabsContent>
            <TabsContent value="prescriptions">
              <div className="my-4">
                {/* TODO: Prescriptions list here */}
                <div className="mt-6 text-center text-gray-400">Your prescriptions will be shown here.</div>
              </div>
            </TabsContent>
            <TabsContent value="history">
              <div className="my-4">
                {/* TODO: Health history here */}
                <div className="mt-6 text-center text-gray-400">Your health history will be shown here.</div>
              </div>
            </TabsContent>
          </Tabs>
        </CardContent>
      </Card>
    </div>
  );
} 